import random

POSITIVE_RESPONSES = [
    "Cool!",
    "Great!",
    "Fantastic!",
    "Wonderful!",
    "Amazing!"
]
NEGATIVE_RESPONSES = [
    "Not really!",
    "You failed!",
    "Try again!",
    "Nope!",
    "Wrong!"
]

def right_guesser_question_answer():
    # Secret value - returning the flag for demonstration - but in reality, this would be secret.
    return "flag{example_secret_flag}"

def play_game(guess: str):
    if guess == right_guesser_question_answer():
        return random.choice(POSITIVE_RESPONSES) + " You found the flag!" + right_guesser_question_answer()
    return random.choice(NEGATIVE_RESPONSES)

def main():
    print("Welcome to the SupEr GUeSsEr G@me!")
    print("Can you guess what I'm thinking?")

    while True:
        user_input = input("Enter your guess: ")

        if user_input.lower() in ["quit", "exit"]:
            print("Thanks for playing!")
            break

        response = play_game(user_input)
        print(response)

if __name__ == "__main__":
    main()
